WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') dvcs,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' allb FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.id_oi,a.mes_scheduling_code,a.production_order,a.product_code,a.machine_code,a.station_code,a.step_code,a.create_date,a.create_time,a.end_date,a.end_time,a.quantity,a.ng,a.transfer,a.status,a.branch_code,count(*) OVER() total FROM public.mes_oi_confirm a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.create_date BETWEEN s.d1 AND s.d2 AND(s.dvcs='' OR a.branch_code=ANY(string_to_array(s.dvcs,',')))AND(s.allb OR a.branch_code=ANY(string_to_array(s.bs,','))) ORDER BY a.create_date DESC,a.create_time DESC LIMIT(SELECT lim FROM p);
